import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

const CreerStudent = () => {
  const [formData, setFormData] = useState({
    nom: "",
    email: "",
    password: "",
    class_id: ""
  });
  const [classes, setClasses] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const navigate = useNavigate();

  // Charger les classes du professeur
  useEffect(() => {
    const fetchClasses = async () => {
      try {
        const token = localStorage.getItem("token");
        const response = await fetch("http://localhost:5000/api/teacher/my-classes", {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });

        const data = await response.json();
        
        if (data.success) {
          setClasses(data.classes);
        } else {
          setError("Erreur lors du chargement des classes");
        }
      } catch (error) {
        console.error("Erreur:", error);
        setError("Erreur de connexion au serveur");
      }
    };

    fetchClasses();
  }, []);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError("");

    try {
      const token = localStorage.getItem("token");
      const response = await fetch("http://localhost:5000/api/students/create", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(formData),
      });

      const data = await response.json();

      if (data.success) {
        alert("✅ Étudiant créé avec succès !");
        navigate("/etudiants");
      } else {
        setError(data.message || "Erreur lors de la création de l'étudiant");
      }
    } catch (error) {
      console.error("Erreur:", error);
      setError("Erreur de connexion au serveur");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ 
      padding: "2rem", 
      maxWidth: "600px", 
      margin: "0 auto",
      fontFamily: "Arial, sans-serif"
    }}>
      <h1 style={{ 
        color: "#2d3748", 
        marginBottom: "2rem",
        textAlign: "center"
      }}>
        Créer un nouvel étudiant
      </h1>

      {error && (
        <div style={{
          padding: "1rem",
          backgroundColor: "#fed7d7",
          color: "#c53030",
          borderRadius: "8px",
          marginBottom: "1.5rem",
          border: "1px solid #feb2b2"
        }}>
          ❌ {error}
        </div>
      )}

      <form onSubmit={handleSubmit} style={{ 
        display: "flex", 
        flexDirection: "column", 
        gap: "1.5rem",
        backgroundColor: "white",
        padding: "2rem",
        borderRadius: "12px",
        boxShadow: "0 4px 6px rgba(0, 0, 0, 0.1)"
      }}>
        <div>
          <label style={{
            display: "block",
            marginBottom: "0.5rem",
            fontWeight: "600",
            color: "#4a5568"
          }}>
            👤 Nom complet *
          </label>
          <input 
            type="text" 
            name="nom"
            placeholder="Ex: Jean Dupont"
            value={formData.nom}
            onChange={handleChange}
            required
            style={{
              width: "100%",
              padding: "0.75rem",
              border: "2px solid #e2e8f0",
              borderRadius: "8px",
              fontSize: "16px",
              transition: "border-color 0.3s"
            }}
            onFocus={(e) => e.target.style.borderColor = "#667eea"}
            onBlur={(e) => e.target.style.borderColor = "#e2e8f0"}
          />
        </div>

        <div>
          <label style={{
            display: "block",
            marginBottom: "0.5rem",
            fontWeight: "600",
            color: "#4a5568"
          }}>
            📧 Email *
          </label>
          <input 
            type="email" 
            name="email"
            placeholder="Ex: jean.dupont@email.com"
            value={formData.email}
            onChange={handleChange}
            required
            style={{
              width: "100%",
              padding: "0.75rem",
              border: "2px solid #e2e8f0",
              borderRadius: "8px",
              fontSize: "16px",
              transition: "border-color 0.3s"
            }}
            onFocus={(e) => e.target.style.borderColor = "#667eea"}
            onBlur={(e) => e.target.style.borderColor = "#e2e8f0"}
          />
        </div>

        <div>
          <label style={{
            display: "block",
            marginBottom: "0.5rem",
            fontWeight: "600",
            color: "#4a5568"
          }}>
            🔒 Mot de passe *
          </label>
          <input 
            type="password" 
            name="password"
            placeholder="Minimum 6 caractères"
            value={formData.password}
            onChange={handleChange}
            required
            minLength="6"
            style={{
              width: "100%",
              padding: "0.75rem",
              border: "2px solid #e2e8f0",
              borderRadius: "8px",
              fontSize: "16px",
              transition: "border-color 0.3s"
            }}
            onFocus={(e) => e.target.style.borderColor = "#667eea"}
            onBlur={(e) => e.target.style.borderColor = "#e2e8f0"}
          />
        </div>

        <div>
          <label style={{
            display: "block",
            marginBottom: "0.5rem",
            fontWeight: "600",
            color: "#4a5568"
          }}>
            🏫 Classe *
          </label>
          <select 
            name="class_id"
            value={formData.class_id}
            onChange={handleChange}
            required
            style={{
              width: "100%",
              padding: "0.75rem",
              border: "2px solid #e2e8f0",
              borderRadius: "8px",
              fontSize: "16px",
              backgroundColor: "white",
              transition: "border-color 0.3s"
            }}
            onFocus={(e) => e.target.style.borderColor = "#667eea"}
            onBlur={(e) => e.target.style.borderColor = "#e2e8f0"}
          >
            <option value="">Sélectionnez une classe</option>
            {classes.map((classe) => (
              <option key={classe.id} value={classe.id}>
                {classe.name} - {classe.niveau} ({classe.annee_scolaire})
              </option>
            ))}
          </select>
        </div>

        <button 
          type="submit" 
          disabled={loading}
          style={{ 
            padding: "0.75rem 1.5rem",
            borderRadius: "8px",
            background: loading ? "#a0aec0" : "#16a34a",
            color: "white",
            border: "none",
            cursor: loading ? "not-allowed" : "pointer",
            fontSize: "16px",
            fontWeight: "600",
            transition: "background-color 0.3s"
          }}
        >
          {loading ? "⏳ Création..." : "📝 Créer l'étudiant"}
        </button>

        <button 
          type="button"
          onClick={() => navigate("/etudiants")}
          style={{ 
            padding: "0.75rem 1.5rem",
            borderRadius: "8px",
            background: "transparent",
            color: "#4a5568",
            border: "2px solid #e2e8f0",
            cursor: "pointer",
            fontSize: "16px",
            fontWeight: "600",
            transition: "all 0.3s"
          }}
          onMouseOver={(e) => {
            e.target.style.backgroundColor = "#f7fafc";
            e.target.style.borderColor = "#cbd5e0";
          }}
          onMouseOut={(e) => {
            e.target.style.backgroundColor = "transparent";
            e.target.style.borderColor = "#e2e8f0";
          }}
        >
          ↩️ Retour à la liste
        </button>
      </form>
    </div>
  );
};

export default CreerStudent;
